using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using MapSharedProps.EditorTools;
public static class Cart192Checks{
 static string Root=>Path.GetFullPath(Path.Combine(Application.dataPath,".."));static string Out=>Path.Combine(Root,"Evidence192");const string Folder="Assets/Imported192-valid",Before="Assets/MapSharedPropsGenerated/Pilot 11";static void Check(bool b,string s){if(!b)throw new Exception(s);}
 static string Shape(Mesh m)=>JsonUtility.ToJson(new Data{p=m.vertices,n=m.normals,uv=m.uv,c=m.colors,t=m.triangles});[Serializable]class Data{public Vector3[] p,n;public Vector2[] uv;public Color[] c;public int[] t;}
 public static void Run(){Directory.CreateDirectory(Out);try{EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var rp=AssetDatabase.LoadAssetAtPath<UniversalRenderPipelineAsset>("Assets/Settings/PC_RPAsset.asset");GraphicsSettings.defaultRenderPipeline=rp;QualitySettings.renderPipeline=rp;var input=Path.Combine(Root,"Input192");var data=new SmallPropsV1.Data{mineCartV1=MineCartV1.Optional(JsonUtility.FromJson<MineCartV1.Data>(File.ReadAllText(Path.Combine(input,"empty.json")))),mineCartLoadV1=MineCartV1.Optional(JsonUtility.FromJson<MineCartV1.Data>(File.ReadAllText(Path.Combine(input,"load.json"))),true)};Check(data.mineCartV1!=null&&data.mineCartLoadV1!=null,"formal optional decode");Check(!AssetDatabase.IsValidFolder(Folder),"fresh output");AssetDatabase.CreateFolder("Assets","Imported192-valid");var root=new GameObject("cart192");var prefabs=new Dictionary<string,GameObject>();Check(MineCartV1.Build(input,Folder,root.transform,prefabs,data)==1&&MineCartV1.Build(input,Folder,root.transform,prefabs,data,true)==1,"two formal placements");AssetDatabase.SaveAssets();
 foreach(var id in new[]{"minecart","minecart_loaded"}){var current=prefabs[id];var old=AssetDatabase.LoadAssetAtPath<GameObject>(Before+"/small-"+id+".prefab");Check(old,"baseline prefab");var m=current.GetComponent<MeshFilter>().sharedMesh;Check(Shape(m)==Shape(old.GetComponent<MeshFilter>().sharedMesh),"geometry normal UV colours exact "+id);Check(current.GetComponents<Collider>().Length>0&&ColliderSnapshot109.Capture(current)==ColliderSnapshot109.Capture(old),"actual collider exact "+id);var mat=current.GetComponent<Renderer>().sharedMaterial;Check(mat.shader.name=="Universal Render Pipeline/Lit"&&mat.GetColor("_BaseColor")==Color.white&&mat.IsKeywordEnabled("_NORMALMAP")&&mat.IsKeywordEnabled("_METALLICSPECGLOSSMAP")&&!mat.IsKeywordEnabled("_EMISSION"),"standard nonemissive metal");Check(m.tangents.Length==m.vertexCount&&!ShaderUtil.ShaderHasError(mat.shader),"tangents and compile");var tread=m.vertices.Where(v=>Mathf.Abs(Mathf.Abs(v.x)-.42f)<.06f&&v.y<.02f).ToArray();Check(tread.Length>0&&Mathf.Abs(tread.Min(v=>v.y))<1e-5,"tread matches .14 rail after placement");Check(current.GetComponentsInChildren<Light>().Length==0,"no lights");}
 var snapshot=ColliderSnapshot109.Capture(root);var materials=root.GetComponentsInChildren<Renderer>().Select(x=>x.sharedMaterial).ToArray();var save=PrefabUtility.SaveAsPrefabAsset(root,Folder+"/placed.prefab");UnityEngine.Object.DestroyImmediate(root);root=(GameObject)PrefabUtility.InstantiatePrefab(save);Check(snapshot==ColliderSnapshot109.Capture(root)&&root.GetComponentsInChildren<Renderer>().Select(x=>x.sharedMaterial).SequenceEqual(materials),"prefab persists actual collider material");var scene=Folder+"/reload.unity";EditorSceneManager.SaveScene(EditorSceneManager.GetActiveScene(),scene);EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);EditorSceneManager.OpenScene(scene);root=UnityEngine.Object.FindObjectsByType<GameObject>(FindObjectsSortMode.None).Single(x=>x.name=="placed");Check(snapshot==ColliderSnapshot109.Capture(root)&&root.GetComponentsInChildren<Renderer>().Select(x=>x.sharedMaterial).SequenceEqual(materials),"scene persists collider material");
 foreach(var phase in new[]{"before","after"}){Cart192Views.Out=Path.Combine(Out,phase);Directory.CreateDirectory(Cart192Views.Out);Cart192Views.folder=phase=="before"?Before:Folder;Cart192Views.Studio();Cart192Views.Field();Cart192Views.Load();Cart192Views.Coexist();}
 File.WriteAllText(Path.Combine(Out,"checks.json"),"{\"pass\":true,\"formalTargets\":2,\"allCatalogueRegenerated\":false,\"geometryUVNormalsColoursUnchanged\":true,\"actualCollidersUnchanged\":true,\"railTreadHeight\":0.14,\"prefabSceneReload\":true,\"nonemissive\":true,\"player\":false}");AssetDatabase.SaveAssets();EditorApplication.Exit(0);
 }catch(Exception e){File.WriteAllText(Path.Combine(Out,"error.txt"),e.ToString());Debug.LogException(e);EditorApplication.Exit(1);}}
}
